# ==============================================================================# 091_COMPANY_ENRICHMENT_ENGINE.py## IOTEC COMPANY ENRICHMENT ENGINE## Missão:# Construir e manter o perfil enriquecido das empresas.## Não cria empresas.# Não resolve identidade.# Apenas enriquece o cadastro mestre.# ==============================================================================from __future__ import annotationsimport sqlite3import jsonimport hashlibfrom pathlib import Pathfrom datetime import datetimeDB = Path("iotec.db")class CompanyEnrichmentEngine:    def __init__(self):        self.conn = sqlite3.connect(DB)        self.conn.row_factory = sqlite3.Row        self.conn.execute("""        CREATE TABLE IF NOT EXISTS commercial_company_profile(            id INTEGER PRIMARY KEY AUTOINCREMENT,            company_uuid TEXT UNIQUE,            phone TEXT,            secondary_phone TEXT,            email TEXT,            secondary_email TEXT,            website TEXT,            linkedin TEXT,            instagram TEXT,            facebook TEXT,            cnpj_status TEXT,            main_activity TEXT,            secondary_activity TEXT,            employees INTEGER,            company_size TEXT,            annual_revenue REAL,            address TEXT,            zip_code TEXT,            latitude REAL,            longitude REAL,            confidence REAL,            source TEXT,            updated_at TEXT,            metadata TEXT,            hash TEXT        )        """)        self.conn.commit()    # ------------------------------------------------------------------    def _sha(self, obj):        raw = json.dumps(            obj,            ensure_ascii=False,            sort_keys=True        )        return hashlib.sha256(raw.encode()).hexdigest()    # ------------------------------------------------------------------    def enrich_company(self, company):        profile = {            "company_uuid": company["company_uuid"],            "phone": "",            "secondary_phone": "",            "email": "",            "secondary_email": "",            "website": "",            "linkedin": "",            "instagram": "",            "facebook": "",            "cnpj_status": "UNKNOWN",            "main_activity": company["segment"],            "secondary_activity": "",            "employees": None,            "company_size": "",            "annual_revenue": None,            "address": "",            "zip_code": "",            "latitude": None,            "longitude": None,            "confidence": company["confidence"],            "source": "MASTER_COMPANY",            "updated_at": datetime.utcnow().isoformat(),            "metadata": {                "origin":"091_COMPANY_ENRICHMENT_ENGINE"            }        }        assinatura = self._sha(profile)        self.conn.execute("""        INSERT OR REPLACE INTO commercial_company_profile(            company_uuid,            phone,            secondary_phone,            email,            secondary_email,            website,            linkedin,            instagram,            facebook,            cnpj_status,            main_activity,            secondary_activity,            employees,            company_size,            annual_revenue,            address,            zip_code,            latitude,            longitude,            confidence,            source,            updated_at,            metadata,            hash        )        VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)        """,(            profile["company_uuid"],            profile["phone"],            profile["secondary_phone"],            profile["email"],            profile["secondary_email"],            profile["website"],            profile["linkedin"],            profile["instagram"],            profile["facebook"],            profile["cnpj_status"],            profile["main_activity"],            profile["secondary_activity"],            profile["employees"],            profile["company_size"],            profile["annual_revenue"],            profile["address"],            profile["zip_code"],            profile["latitude"],            profile["longitude"],            profile["confidence"],            profile["source"],            profile["updated_at"],            json.dumps(profile["metadata"], ensure_ascii=False),            assinatura        ))        self.conn.commit()    # ------------------------------------------------------------------    def process_all(self):        empresas = self.conn.execute("""            SELECT *            FROM commercial_master_company            ORDER BY id        """).fetchall()        total = 0        for empresa in empresas:            self.enrich_company(dict(empresa))            total += 1        return total# ==============================================================================# TESTE# ==============================================================================if __name__ == "__main__":    engine = CompanyEnrichmentEngine()    total = engine.process_all()    print("="*80)    print("COMPANY ENRICHMENT")    print("="*80)    print(f"Empresas enriquecidas : {total}")    print("Status                : SUCCESS")    print("="*80)